            "cargo test --lib application::workflow::tests::round_base -- --test-threads=1",
            "cargo test --lib application::workflow::tests::candidate_refresh -- --test-threads=1",
            "cargo test --lib application::workflow::tests::quality_base_refresh -- --test-threads=1",
            "cargo test --lib application::workflow::governance::integration::tests -- --test-threads=1",
            "cargo test --lib infrastructure::git::worktrees::tests -- --test-threads=1",
            "cargo test --lib application::events::tests -- --test-threads=1",
            "Run focused tests for any new lineage, publication and handoff modules, then cargo check --all-targets and formatting checks scoped to changed Rust modules.",
